#include <bits/stdc++.h>
using namespace std;

struct Item {
    string name;
    int q;
    long long v, m, l;
};

int n;
Item items[12];
long long bestVal;
int bestSol[12];
int curSol[12];
long long capM = 20000000LL, capL = 25000000LL;

// LP relaxation upper bound for items[idx..n-1] with remaining mass rm, volume rl
// Items sorted by value/max(m/capM, l/capL) or similar
double lpBound(int idx, long long rm, long long rl, long long curVal) {
    double ub = (double)curVal;
    for (int i = idx; i < n; i++) {
        if (items[i].m == 0 && items[i].l == 0) {
            ub += (double)items[i].v * items[i].q;
            continue;
        }
        long long maxByM = (items[i].m > 0) ? rm / items[i].m : (long long)items[i].q;
        long long maxByL = (items[i].l > 0) ? rl / items[i].l : (long long)items[i].q;
        long long canTake = min({(long long)items[i].q, maxByM, maxByL});
        if (canTake >= items[i].q) {
            ub += (double)items[i].v * items[i].q;
            rm -= items[i].m * items[i].q;
            rl -= items[i].l * items[i].q;
        } else {
            // Fractional: limited by mass or volume
            double fracM = (items[i].m > 0) ? (double)rm / items[i].m : 1e18;
            double fracL = (items[i].l > 0) ? (double)rl / items[i].l : 1e18;
            double frac = min({(double)items[i].q, fracM, fracL});
            ub += (double)items[i].v * frac;
            break; // greedy LP relaxation: after fractional, remaining items get 0
        }
    }
    return ub;
}

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (idx == n) {
        if (curVal > bestVal) {
            bestVal = curVal;
            memcpy(bestSol, curSol, sizeof(bestSol));
        }
        return;
    }

    if (lpBound(idx, rm, rl, curVal) <= (double)bestVal + 0.5)
        return;

    long long maxByM = (items[idx].m > 0) ? rm / items[idx].m : (long long)items[idx].q;
    long long maxByL = (items[idx].l > 0) ? rl / items[idx].l : (long long)items[idx].q;
    int maxTake = (int)min({(long long)items[idx].q, maxByM, maxByL});

    // Try from max down for better pruning
    for (int k = maxTake; k >= 0; k--) {
        curSol[idx] = k;
        solve(idx + 1, rm - (long long)k * items[idx].m, rl - (long long)k * items[idx].l, curVal + (long long)k * items[idx].v);
    }
    curSol[idx] = 0;
}

int main(){
    string input((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());

    // Parse JSON
    vector<pair<string, vector<long long>>> entries;
    size_t pos = 0;
    while(true) {
        pos = input.find('"', pos);
        if (pos == string::npos) break;
        size_t end = input.find('"', pos+1);
        string key = input.substr(pos+1, end-pos-1);
        pos = end+1;

        // find '['
        size_t br = input.find('[', pos);
        if (br == string::npos) break;
        size_t br2 = input.find(']', br);
        string arr = input.substr(br+1, br2-br-1);
        pos = br2+1;

        // parse numbers from arr
        vector<long long> nums;
        stringstream ss(arr);
        string token;
        while(getline(ss, token, ',')) {
            long long val = 0;
            bool neg = false;
            for (char c : token) {
                if (c == '-') neg = true;
                if (c >= '0' && c <= '9') val = val*10 + (c-'0');
            }
            if (neg) val = -val;
            nums.push_back(val);
        }
        if (nums.size() == 4) {
            entries.push_back({key, nums});
        }
    }

    n = entries.size();
    for (int i = 0; i < n; i++) {
        items[i].name = entries[i].first;
        items[i].q = (int)entries[i].second[0];
        items[i].v = entries[i].second[1];
        items[i].m = entries[i].second[2];
        items[i].l = entries[i].second[3];
    }

    // Sort by value density (value per unit of "tighter" resource) descending for LP bound
    sort(items, items+n, [](const Item& a, const Item& b){
        // Sort by v / max(m/20e6, l/25e6) descending
        // = v / max(m*25, l*20) * 500e6
        double da = (double)a.v / max(a.m * 25.0, a.l * 20.0);
        double db = (double)b.v / max(b.m * 25.0, b.l * 20.0);
        return da > db;
    });

    bestVal = -1;
    memset(bestSol, 0, sizeof(bestSol));
    memset(curSol, 0, sizeof(curSol));

    solve(0, capM, capL, 0);

    // Output
    cout << "{\n";
    // Need to output in original key order? Let's output sorted by name or items order
    for (int i = 0; i < n; i++) {
        cout << " \"" << items[i].name << "\": " << bestSol[i];
        if (i < n-1) cout << ",";
        cout << "\n";
    }
    cout << "}\n";

    return 0;
}
